/* The doors: walk there; at the step the door slides (regions 0, 1).
 * [MSG_WALK 22 00 00] */
static void mudd3_WalkToUpperDoor(void)
{
    fv_going_door = 1;
    room.busy = 1;
    svc_Walk(0, 0xB8, 0x70, 0);
    return;
}

/* [MSG_REGION 00 00 00] */
static void mudd3_ReachUpperDoor(void)
{
    if (fv_going_door == 1) {
        svc_Sfx(N_SMADOOR3);
        svc_Anim0(0xC, N_s4lbdo, 0xBA, 0x6F, 0);
    }
    return;
}

